import math
from functools import reduce

def gcd_multiple(numbers):
    return reduce(math.gcd, numbers)

def find_divisible_number(n, a):
    gcd_value = gcd_multiple(a)
    if all(x % gcd_value == 0 for x in a):
        return gcd_value
    else:
        return -1

# Input reading
